import json

def process_table(table_code, caption, supplementary_text, target_cells):
    # Determine the table structure from the caption
    table_structure = {
        "In2Se3 film": ["Peak position", "FWHM", "Peak area"],
        "InSe2 film": ["Peak position", "FWHM", "Peak area"]
    }
    if "Glass" in caption:
        table_structure = {
            "Sample": ["Sample", "Composition"],
            "Composition": ["Composition"]
        }
    elif "Crystal phase" in caption:
        table_structure = {
            "Crystal phase": ["Crystal phase"],
            "JCPDS reference files": ["JCPDS reference files"]
        }

    # Determine the record type for each cell
    cell_index = []
    cell_record = []
    for i, value in enumerate(target_cells["cell_value_processed"]):
        row = table_structure[table_structure.keys()[i // len(table_structure[table_structure.keys()[0]])]]
        col = row[i % len(row)]
        if "Glass" in caption and col in ["Composition"]:
            if col == "Composition":
                if "mol%" in table_code or "mol" in table_code or "wt%" in table_code or "wt" in table_code:
                    record_type = "Glass_Compound_Amount"
                else:
                    record_type = "Other"
            else:
                record_type = "Other"
        elif "Crystal phase" in caption and col == "Crystal phase":
            record_type = "Other"
        else:
            record_type = "Other"

        cell_index.append([target_cells["i"][i], target_cells["j"][i], target_cells["k"][i]])
        if record_type == "Glass_Compound_Amount":
            if "mol%" in table_code or "mol" in table_code:
                unit = "mol"
            elif "wt%" in table_code or "wt" in table_code:
                unit = "wt"
            else:
                unit = "xx"
            cell_record.append(json.dumps({
                "value": value,
                "type": record_type,
                "constituent": col,
                "unit": unit,
                "material": table_structure[table_structure.keys()[i // len(table_structure[table_structure.keys()[0]])]][0]
            }))
        else:
            cell_record.append(json.dumps({
                "value": value,
                "type": record_type
            }))

    # Verify the output
    assert len(cell_index) == len(cell_record) == len(target_cells["cell_value_processed"])
    for i in range(len(cell_index)):
        assert cell_index[i] == [target_cells["i"][i], target_cells["j"][i], target_cells["k"][i]]
        assert cell_record[i]["value"] == target_cells["cell_value_processed"][i]

    return json.dumps({
        "cell_index": cell_index,
        "cell_record": cell_record
    })

