import json

def process_table(table_code, target_cells):
    # Define the table headers
    headers = {
        "Raman frequency (cm-1)": ["Folding of the TA modes coming from Brillouin zone boundary", "g-In2Se3 crystal related zone center mode", "In-Se vibrations", "Folding of the TO and LO modes coming from Brillouin zone boundary", "Se chain vibrations", "Se8 rings vibrations", "Second order RS"],
        "Suggested type of vibration": ["", "", "", "", "", "", ""]
    }

    # Initialize the output
    cell_index = []
    cell_record = []

    # Iterate over the target cells
    for i, j, k, value in zip(target_cells["i"], target_cells["j"], target_cells["k"], target_cells["cell_value_processed"]):
        # Determine the record type
        if "Glass" in table_code and "Composition" in table_code:
            if "mol%" in table_code or "mol" in table_code or "wt%" in table_code or "wt" in table_code:
                record_type = "Glass_Compound_Amount"
            else:
                record_type = "Other"
        else:
            record_type = "Other"

        # Determine the constituent and material
        if record_type == "Glass_Compound_Amount":
            # Find the row and column headers
            for header in headers:
                if i == headers[header].index(j):
                    row_header = header
                if j == headers[header].index(i):
                    col_header = header

            # Determine the constituent and material
            if row_header == "Raman frequency (cm-1)":
                constituent = headers["Suggested type of vibration"][j]
            else:
                constituent = row_header

            if col_header == "Sample":
                material = headers["Suggested type of vibration"][i]
            else:
                material = headers["Suggested type of vibration"][i]

            # Normalize the unit
            if "mol%" in table_code:
                unit = "mol"
            elif "mol" in table_code:
                unit = "mol"
            elif "wt%" in table_code:
                unit = "wt"
            elif "wt" in table_code:
                unit = "wt"

            # Create the record
            record = {
                "value": value,
                "type": record_type,
                "constituent": constituent,
                "unit": unit,
                "material": material
            }
        else:
            # Create the record
            record = {
                "value": value,
                "type": record_type
            }

        # Add the record to the output
        cell_index.append([i, j, k])
        cell_record.append(json.dumps(record))

