            if unit == 'mol%':
                unit = 'mol'
            elif unit == 'wt%':
                unit = 'wt'

            # Create JSON record
            record = {
                'value': value,
                'type': 'Glass_Compound_Amount',
                'constituent': constituent,
                'unit': unit,
                'material': material
            }
        else:
            record = {
                'value': value,
                'type': 'Other'
            }

        # Serialize record to JSON string
        record_json = json.dumps(record)

