                else:
                    record_types.append('Other')
            else:
                record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create cell records
    cell_records = []
    for i, j, k, record_type in zip(target_cells['i'], target_cells['j'], target_cells['k'], record_types):
        if record_type == 'Glass_Compound_Amount':
            # Extract material and constituent from headers
            material = headers[0].split(' - ')[0]
            if material == 'ST40' or material == 'ST20':
                material = 'xx'
            constituent = headers[j].replace(' ', '')
            if headers[j].endswith('%'):
                unit = 'wt' if headers[j].startswith('wt') else 'mol'
            else:
                unit = 'wt' if headers[j].startswith('wt') else 'mol'
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)], 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
        else:
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)], 'type': 'Other'}))

    # Create cell indices
    cell_indices = [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])]

