    elif 'Crystal phase' in table_code:
        headers = {'Crystal phase': ['Crystal phase'], 'JCPDS reference files': ['JCPDS reference files']}

    # Determine the record type for each cell
    cell_record = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers['Assignments'][j] == 'Assignments':
            if 'SiO4' in headers['Assignments'][i]:
                if 'stretching' in headers['Assignments'][i]:
                    if 'Si-O-Si' in headers['Assignments'][i]:
                        if 'symmetric' in headers['Assignments'][i]:
                            record_type = 'Glass_Compound_Amount'
                        else:
                            record_type = 'Other'
                    elif 'O-Si-O' in headers['Assignments'][i]:
                        if 'symmetric' in headers['Assignments'][i]:
                            record_type = 'Glass_Compound_Amount'
                        else:
                            record_type = 'Other'
                    else:
                        record_type = 'Other'
                elif 'bending' in headers['Assignments'][i]:
                    record_type = 'Other'
                else:
                    record_type = 'Other'
            elif 'P-O-P' in headers['Assignments'][i]:
                if 'stretching' in headers['Assignments'][i]:
                    record_type = 'Glass_Compound_Amount'
                else:
