        if record_type == 'Glass_Compound_Amount':
            record = {
                'value': target_cells['cell_value_processed'][target_cells['i'].index(i)],
                'type': record_type,
                'constituent': headers['Assignments'][i],
                'unit': unit,
                'material': material
            }
        else:
            record = {
                'value': target_cells['cell_value_processed'][target_cells['i'].index(i)],
                'type': record_type
            }

        # Serialize the record to a JSON string
        record = json.dumps(record)

        # Add the record to the list
        cell_record.append(record)

    # Create the output dictionary
    output = {
        'cell_index': [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])],
