import json

def process_table(table_code, caption, supplementary_text, target_cells):
    # Determine the table structure from the caption
    rows = caption.split('\n')
    headers = rows[0].split(' | ')
    columns = rows[1].split(' | ')
    column_headers = [header.split(' | ')[0] for header in columns]

    # Determine the record type for each cell
    record_types = []
    for i, value in enumerate(target_cells['cell_value_processed']):
        if 'Composition' in column_headers[j] and 'mol%' in columns[j] or 'wt%' in columns[j]:
            record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create the output JSON object
    output = {
        'cell_index': [],
        'cell_record': []
    }

    for i, value in enumerate(target_cells['cell_value_processed']):
        # Determine the record type and create the record
        if record_types[i] == 'Glass_Compound_Amount':
            # Determine the constituent and material
            if 'Sample' in column_headers[j]:
                material = columns[j].split(' | ')[0]
            else:
                material = 'xx'
            if 'Fe2+/SFe' in column_headers[j]:
                constituent = 'Fe2+/SFe'
            else:
                constituent = columns[j].split(' | ')[0]
            if 'mol%' in columns[j]:
                unit = 'mol'
            elif 'wt%' in columns[j]:
                unit = 'wt'
            else:
                unit = 'xx'
            record = {
                'value': value,
                'type': 'Glass_Compound_Amount',
                'constituent': constituent,
                'unit': unit,
                'material': material
            }
        else:
            record = {
                'value': value,
                'type': 'Other'
            }

        # Create the cell index and record string
        cell_index = [target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]]
        record_str = json.dumps(record)

        # Add the cell index and record to the output
        output['cell_index'].append(cell_index)
        output['cell_record'].append(record_str)

    # Verify the output
    assert len(output['cell_index']) == len(target_cells['cell_value_processed'])
    assert len(output['cell_record']) == len(target_cells['cell_value_processed'])
    for i in range(len(output['cell_index'])):
        assert output['cell_index'][i] == [target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]]
        assert output['cell_record'][i] == json.dumps({
            'value': target_cells['cell_value_processed'][i],
            'type': record_types[i]
        })

    # Return the output as a JSON string
    return json.dumps(output)

