import json

def process_table(table_code, target_cells):
    # Extract table headers
    headers = table_code.split('\n')[0].split('|')

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers[i] == 'Spectral region' or headers[j] == 'Given research' or headers[j] == 'Literature data':
            record_types.append('Other')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Efimov [13], metaphosphate glasses':
            record_types.append('Glass_Compound_Amount')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Scholze [4-6], any glasses':
            record_types.append('Glass_Compound_Amount')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Efimov and Pogareva [14], silicate glasses':
            record_types.append('Glass_Compound_Amount')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Boulos and Glebov [11,15], a silicate glass':
            record_types.append('Glass_Compound_Amount')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Efimov et al. [12], pyrophosphate glasses':
            record_types.append('Glass_Compound_Amount')
        elif headers[i] == 'Inherent band frequencies (cm-1)' and headers[j] == 'Literature data':
            record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create cell records
    cell_records = []
    for value, record_type in zip(target_cells['cell_value_processed'], record_types):
        if record_type == 'Glass_Compound_Amount':
            if headers[i] == 'Inherent band frequencies (cm-1)':
                if headers[j] == 'Efimov [13], metaphosphate glasses':
                    constituent = 'metaphosphate glasses'
                elif headers[j] == 'Scholze [4-6], any glasses':
                    constituent = 'any glasses'
                elif headers[j] == 'Efimov and Pogareva [14], silicate glasses':
                    constituent = 'silicate glasses'
                elif headers[j] == 'Boulos and Glebov [11,15], a silicate glass':
                    constituent = 'a silicate glass'
                elif headers[j] == 'Efimov et al. [12], pyrophosphate glasses':
                    constituent = 'pyrophosphate glasses'
                elif headers[j] == 'Literature data':
                    constituent = 'literature data'
            else:
                constituent = headers[j]
            if headers[i] == 'Inherent band frequencies (cm-1)':
                unit = 'cm-1'
            else:
                unit = headers[i]
            if headers[0] == 'Sample' or headers[0] == 'No.':
                material = headers[0]
            else:
                material = 'xx'
            cell_records.append(json.dumps({'value': value, 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
        else:
            cell_records.append(json.dumps({'value': value, 'type': 'Other'}))

    # Create output dictionary
    output = {
        'cell_index': list(zip(target_cells['i'], target_cells['j'], target_cells['k'])),
        'cell_record': cell_records
    }

    return json.dumps(output)

