import json

def process_table(table_code, target_cells):
    # Extract table headers
    headers = table_code.split('\n')[0].split('|')

    # Determine record type for each cell
    record_types = []
    for i, value in enumerate(target_cells['cell_value_processed']):
        if headers[1] == 'Composition (at.%)' and headers[0] == 'Composition (at.%)':
            if headers[2] == 'Composition (at.%)':
                if headers[3] == 'Density':
                    record_types.append('Other')
                else:
                    record_types.append('Glass_Compound_Amount')
            else:
                record_types.append('Glass_Compound_Amount')
        elif headers[0] == 'Density':
            record_types.append('Other')
        else:
            record_types.append('Other')

    # Create cell records
    cell_records = []
    for i, value in enumerate(target_cells['cell_value_processed']):
        if record_types[i] == 'Glass_Compound_Amount':
            if headers[0] == 'Composition (at.%)':
                if headers[1] == 'Composition (at.%)':
                    if headers[2] == 'Composition (at.%)':
                        if headers[3] == 'Density':
                            constituent = headers[4]
                            unit = 'wt'
                        else:
                            constituent = headers[3]
                            unit = 'mol'
                    else:
                        constituent = headers[2]
                        unit = 'mol'
                else:
                    constituent = headers[1]
                    unit = 'wt'
            else:
                constituent = headers[0]
                unit = 'Other'
            material = 'xx'
            if headers[0] == 'BS 75-10-15':
                material = 'BS 75-10-15'
            elif headers[0] == 'BS 80-10-10':
                material = 'BS 80-10-10'
            elif headers[0] == 'Commercial':
                material = 'Commercial'
            cell_records.append(json.dumps({'value': value, 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
        else:
            cell_records.append(json.dumps({'value': value, 'type': 'Other'}))

    # Create cell index
    cell_index = [[target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]] for i in range(len(target_cells['i']))]

    # Verify output
    assert len(cell_index) == len(cell_records) == len(target_cells['cell_value_processed'])
