import json

def process_table(table_code, target_cells):
    # Define the table headers
    headers = {
        'Molar composition (mol%)': ['Ga2S3', 'Na2S', 'La2S3', 'La2O3', 'LaF3'],
        'Refractive index': ['1.20 mm', '1.52 mm'],
        'Absorption edge': ['(nm)']
    }

    # Determine the table structure
    table_structure = {}
    for i, header in enumerate(headers):
        table_structure[i] = {}
        for j, value in enumerate(headers[header]):
            table_structure[i][j] = value

    # Process the target cells
    cell_index = []
    cell_record = []
    for i, value in enumerate(target_cells['cell_value_processed']):
        row = target_cells['i'][i]
        col = target_cells['j'][i]
        k = target_cells['k'][i]

        # Determine the record type
        if table_structure[row][col] in ['Molar composition (mol%)']:
            record_type = 'Glass_Compound_Amount'
            constituent = table_structure[row][col]
            unit = 'mol'
            material = 'xx'
            if 'GL' in table_code:
                material = table_code.split(' ')[0]
            if 'GLSO' in table_code:
                material = table_code.split(' ')[0]
            if 'GLSOF' in table_code:
                material = table_code.split(' ')[0]
            if 'GNS' in table_code:
                material = table_code.split(' ')[0]
        else:
            record_type = 'Other'

        # Create the record
        if record_type == 'Glass_Compound_Amount':
            record = {
                'value': value,
                'type': record_type,
                'constituent': constituent,
                'unit': unit,
                'material': material
            }
        else:
            record = {
                'value': value,
                'type': record_type
            }

        # Serialize the record
        record_json = json.dumps(record)

        # Add the record to the list
        cell_index.append([row, col, k])
        cell_record.append(record_json)

    # Verify the output
    assert len(cell_index) == len(cell_record) == len(target_cells['cell_value_processed'])
    for i in range(len(cell_index)):
        assert cell_index[i] == [target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]]
        assert cell_record[i] == json.dumps({
            'value': target_cells['cell_value_processed'][i],
            'type': 'Glass_Compound_Amount' if table_structure[target_cells['i'][i]][target_cells['j'][i]] in ['Molar composition (mol%)'] else 'Other'
        })

    # Return the result
    return json.dumps({
        'cell_index': cell_index,
        'cell_record': cell_record
    })

