    rows = caption.split('\n')
    headers = rows[0].split(' | ')
    columns = rows[1].split(' | ')
    column_headers = [header.split(' ')[0] for header in columns]

    # Determine the record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if 'Glass' in column_headers[j] and 'Comp' in column_headers[j] and ('mol%' in columns[j] or 'mol' in columns[j] or 'wt%' in columns[j] or 'wt' in columns[j]):
            record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create the output JSON object
    output = {
        'cell_index': [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])],
        'cell_record': []
    }

    # Populate the cell_record array
    for i, j, k, record_type in zip(target_cells['i'], target_cells['j'], target_cells['k'], record_types):
        if record_type == 'Glass_Compound_Amount':
            # Extract the constituent and material from the column headers
            constituent = columns[j].split('(')[0].strip()
            material = headers[j].split('(')[0].strip()
            if material == 'xx':
                material = 'xx'
