                unit = 'mol'
            elif 'mol' in columns[j]:
                unit = 'mol'
            elif 'wt%' in columns[j]:
                unit = 'wt'
            elif 'wt' in columns[j]:
                unit = 'wt'
            # Create the record
            record = {
                'value': target_cells['cell_value_processed'][target_cells['i'].index(i)],
                'type': 'Glass_Compound_Amount',
                'constituent': constituent,
                'unit': unit,
                'material': material
            }
