            record = {
                'value': target_cells['cell_value_processed'][target_cells['i'].index(i)],
                'type': 'Other'
            }
        # Serialize the record as a JSON string and add it to the output
        output['cell_record'].append(json.dumps(record))

    return json.dumps(output)
