    headers = table_code.split('\n')[0].split(' | ')

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if caption.startswith('Composition and linear optical properties'):
            if headers[j].startswith('Molar composition ('):
                if headers[j].endswith(')'):
                    record_types.append('Glass_Compound_Amount')
                else:
                    record_types.append('Other')
            else:
                record_types.append('Other')
        elif caption.startswith('Thermal property and refractive index'):
            if headers[j] in ['Tg (degC)+-(3degC)', 'Tx (degC)+-(3degC)', 'DT (Tx -Tg) (degC)+-(6degC)', 'n (+-0.0003) at 632.8nm']:
                record_types.append('Other')
            else:
                record_types.append('Other')
