                        constituent = headers[j][17:-1]
                        material = headers[0]
                    else:
                        constituent = headers[j]
                        material = headers[0]
                else:
                    constituent = headers[j]
                    material = headers[0]
                if headers[j].endswith(')'):
                    unit = 'mol'
                else:
