                constituent = headers[j]
                material = headers[0]
                unit = 'degC'
            elif caption.startswith('List of JCPDS files'):
                constituent = headers[j]
                material = headers[0]
                unit = ''
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)], 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
        else:
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)], 'type': 'Other'}))

    # Create cell indices
    cell_indices = [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])]

    # Verify output
    assert len(cell_indices) == len(cell_records) == len(target_cells['cell_value_processed'])
    for i, j, k in cell_indices:
        assert [i, j, k] == [target_cells['i'][target_cells['i'].index(i)], target_cells['j'][target_cells['j'].index(j)], target_cells['k'][target_cells['k'].index(k)]
    for record in cell_records:
        assert json.loads(record)['value'] == target_cells['cell_value_processed'][target_cells['i'].index(target_cells['i'][cell_records.index(record)])]

    # Return JSON object
    return json.dumps({'cell_index': cell_indices, 'cell_record': cell_records})

