                unit = 'mol'
            # Create the record
            record = json.dumps({'value': value, 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material})
        else:
            # Create the record
            record = json.dumps({'value': value, 'type': 'Other'})
        # Add the cell index and record to the lists
        cell_index.append([i, headers.index(headers[j]) + 1, k])
        cell_record.append(record)

    # Verify the output
    assert len(cell_index) == len(cell_record) == len(target_cells['cell_value_processed'])
    for i, (index, record) in enumerate(zip(cell_index, cell_record)):
        assert index == [target_cells['i'][i], target_cells['j'][i] + 1, target_cells['k'][i]]
        assert record == json.loads(record)

    # Return the result
    return json.dumps({'cell_index': cell_index, 'cell_record': cell_record})

