import json

def process_table(table_code, target_cells):
    # Extract table headers
    headers = table_code.split('\n')[0].split(' | ')

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers[j].startswith('Molecular') and headers[i].startswith('Sample'):
            if headers[i+1].startswith('Mol'):
                record_types.append('Glass_Compound_Amount')
            else:
                record_types.append('Other')
        elif headers[j].startswith('Molar') and headers[i].startswith('Glass'):
            record_types.append('Glass_Compound_Amount')
        else:
            record_types.append('Other')

    # Create cell records
    cell_records = []
    for i, j, k, record_type in zip(target_cells['i'], target_cells['j'], target_cells['k'], record_types):
        if record_type == 'Glass_Compound_Amount':
            # Extract constituent and material from headers
            if headers[i].startswith('Sample'):
                material = headers[i].split(' ')[1]
            else:
                material = 'xx'
            if headers[j].startswith('Mol'):
                unit = 'mol'
            elif headers[j].startswith('wt'):
                unit = 'wt'
            else:
                unit = 'xx'
            constituent = headers[j]
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)*6+j], 'type': 'Glass_Compound_Amount', 'constituent': constituent, 'unit': unit, 'material': material}))
        else:
            cell_records.append(json.dumps({'value': target_cells['cell_value_processed'][target_cells['i'].index(i)*6+j], 'type': 'Other'}))

    # Create cell indices
    cell_indices = [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])]

    # Verify output
    assert len(cell_indices) == len(cell_records) == len(target_cells['cell_value_processed'])
    for i, j, k in cell_indices:
        assert [i, j, k] == [target_cells['i'][target_cells['i'].index(i)], target_cells['j'][target_cells['j'].index(j)], target_cells['k'][target_cells['k'].index(k)]
