import json

def process_table(table_code, target_cells):
    # Define the table headers
    headers = table_code.splitlines()[0].split("|")[1:]

    # Initialize the result
    result = {"cell_index": [], "cell_record": []}

    # Iterate over the target cells
    for i, value, j, k in zip(target_cells["i"], target_cells["cell_value_processed"], target_cells["j"], target_cells["k"]):
        # Determine the record type
        if headers[j].startswith("Glasses") or headers[j].startswith("Glass"):
            record_type = "Glass_Compound_Amount"
        elif headers[j].startswith("Temperature") or headers[j].startswith("Tg") or headers[j].startswith("Tx") or headers[j].startswith("DT"):
            record_type = "Other"
        elif headers[j].startswith("Crystal") or headers[j].startswith("JCPDS"):
            record_type = "Other"
        else:
            record_type = "Other"

        # Determine the constituent and material
        if record_type == "Glass_Compound_Amount":
            if headers[j].startswith("Glasses") or headers[j].startswith("Glass"):
                material = headers[i].split("(")[0].strip()
            else:
                material = "xx"
            if headers[j].startswith("Molar composition"):
                unit = "mol"
            elif headers[j].startswith("wt"):
                unit = "wt"
            else:
                unit = "xx"
            constituent = headers[j].split("(")[0].strip()
        else:
            constituent = "xx"
            material = "xx"
            unit = "xx"

        # Create the record
        if record_type == "Glass_Compound_Amount":
            record = {
                "value": value,
                "type": record_type,
                "constituent": constituent,
                "unit": unit,
                "material": material
            }
        else:
            record = {
                "value": value,
                "type": record_type
            }

        # Add the record to the result
        result["cell_index"].append([i, j, k])
        result["cell_record"].append(json.dumps(record))

    # Verify the result
    assert len(result["cell_index"]) == len(target_cells["cell_value_processed"])
    assert len(result["cell_record"]) == len(target_cells["cell_value_processed"])
    for i, j, k, value in zip(result["cell_index"], target_cells["j"], target_cells["k"], target_cells["cell_value_processed"]):
        assert i == [target_cells["i"][result["cell_index"].index([i, j, k])], j, k]
        assert json.loads(result["cell_record"][result["cell_index"].index([i, j, k])])["value"] == value

    # Return the result
    return json.dumps(result)

