    # Determine record type for each cell
    record_types = []
    for i, value in enumerate(target_cells['cell_value_processed']):
        if 'mol%' in headers[1] or 'wt%' in headers[1]:
            if headers[1].startswith('Molar composition ('):
                if 'La' in value or 'Ga' in value or 'Na' in value:
                    record_types.append('Glass_Compound_Amount')
                else:
                    record_types.append('Other')
            elif headers[1].startswith('Glass'):
                record_types.append('Glass_Compound_Amount')
            else:
                record_types.append('Other')
        elif 'Tg' in headers[1] or 'Tx' in headers[1] or 'DT' in headers[1]:
            record_types.append('Other')
        elif 'JCPDS' in headers[1]:
            record_types.append('Other')
        else:
            record_types.append('Other')

