    response = {
        "cell_index": [[target_cells['i'][i], target_cells['j'][i], target_cells['k'][i]] for i in range(len(target_cells['cell_value_processed']))],
        "cell_record": []
    }

    for i, value in enumerate(target_cells['cell_value_processed']):
        if record_types[i] == 'Glass_Compound_Amount':
            if 'mol%' in headers[1] or 'wt%' in headers[1]:
                if 'La' in value or 'Ga' in value or 'Na' in value:
                    constituent = value
                else:
                    constituent = headers[1].split('(')[0].split(' ')[-1]
                if 'mol%' in headers[1]:
                    unit = 'mol'
                else:
                    unit = 'wt'
                if 'GLS' in headers[0]:
                    material = 'GLS'
                elif 'GLSO' in headers[0]:
                    material = 'GLSO'
                elif 'GLSOF' in headers[0]:
                    material = 'GLSOF'
                elif 'GNS' in headers[0]:
                    material = 'GNS'
                else:
                    material = 'xx'
                response['cell_record'].append(json.dumps({"value": value, "type": "Glass_Compound_Amount", "constituent": constituent, "unit": unit, "material": material}))
            else:
                response['cell_record'].append(json.dumps({"value": value, "type": "Glass_Compound_Amount", "constituent": headers[1].split('(')[0].split(' ')[-1], "unit": headers[1].split('(')[1].split(')')[0], "material": headers[0]}))
