                if line.split()[0] == table_code.splitlines()[0].split()[j]:
                    if 'mol%' in headers[0] or 'mol' in headers[0]:
                        unit = 'mol'
                    elif 'wt%' in headers[0] or 'wt' in headers[0]:
                        unit = 'wt'
                    else:
