    headers = {
        "Sample name": 0,
        "Nominal composition": 1,
        "Nominal composition": 2,
        "Density, r": 3,
        "Ultrasonic velocity": 4,
        "Ultrasonic velocity": 5,
        "Attenuation, a": 6,
        "Transition temperature T g": 7
    }

    # Determine the record type for each cell
    record_types = []
    for i, j, k in zip(target_cells["i"], target_cells["j"], target_cells["k"]):
        if headers[target_cells["j"][j]] == "Nominal composition":
            if "PbO" in table_code[i] or "Bi2O3" in table_code[i]:
                record_types.append("Glass_Compound_Amount")
            else:
                record_types.append("Other")
        else:
            record_types.append("Other")

    # Create the output dictionary
    output = {
        "cell_index": [],
        "cell_record": []
    }

    # Populate the output dictionary
    for i, j, k, record_type in zip(target_cells["i"], target_cells["j"], target_cells["k"], record_types):
        if record_type == "Glass_Compound_Amount":
            # Extract the constituent and material from the table code
            if "PbO" in table_code[i]:
                constituent = "PbO"
                material = "xx"
            elif "Bi2O3" in table_code[i]:
                constituent = "Bi2O3"
                material = "xx"
            else:
                raise ValueError("Unknown constituent")

            # Determine the unit
            if "wt" in table_code[i]:
                unit = "wt"
            elif "mol" in table_code[i]:
                unit = "mol"
            else:
                raise ValueError("Unknown unit")

            # Create the record
            record = {
                "value": target_cells["cell_value_processed"][i],
                "type": "Glass_Compound_Amount",
                "constituent": constituent,
                "unit": unit,
                "material": material
            }
        else:
            # Create the record
            record = {
                "value": target_cells["cell_value_processed"][i],
                "type": "Other"
            }

        # Add the record to the output dictionary
        output["cell_index"].append([i, j, k])
        output["cell_record"].append(json.dumps(record))

    return json.dumps(output)

