import json

def process_table(table_code, caption, target_cells):
    # Parse table headers
    headers = [header.strip() for header in table_code.splitlines()[0].split("|")[1:]]

    # Determine record type for each cell
    record_types = []
    for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k']):
        if headers[j].startswith("Molar composition (") and headers[i].endswith("%"):
            record_types.append("Glass_Compound_Amount")
        elif headers[j].startswith("Molar composition (") and headers[i].endswith(")"):
            record_types.append("Glass_Compound_Amount")
        elif headers[j].startswith("Refractive index") or headers[j].startswith("Absorption edge"):
            record_types.append("Other")
        elif headers[j].startswith("Tg") or headers[j].startswith("Tx") or headers[j].startswith("DT"):
            record_types.append("Other")
        elif headers[j].startswith("Crystal phase"):
            record_types.append("Other")
        else:
            record_types.append("Other")

    # Create cell records
    cell_records = []
    for i, j, k, record_type in zip(target_cells['i'], target_cells['j'], target_cells['k'], record_types):
        if record_type == "Glass_Compound_Amount":
            # Extract chemical constituent and material from headers
            constituent = headers[i]
            material = caption.split(" of ")[0]
            if "mol%" in headers[j]:
                unit = "mol"
            elif "wt%" in headers[j]:
                unit = "wt"
            else:
                unit = "xx"
            # Create record
            record = {
                "value": target_cells['cell_value_processed'][target_cells['i'].index(i)],
                "type": "Glass_Compound_Amount",
                "constituent": constituent,
                "unit": unit,
                "material": material
            }
        else:
            # Create record
            record = {
                "value": target_cells['cell_value_processed'][target_cells['i'].index(i)],
                "type": "Other"
            }
        # Serialize record to JSON string
        cell_records.append(json.dumps(record))

    # Create output dictionary
    output = {
        "cell_index": [[i, j, k] for i, j, k in zip(target_cells['i'], target_cells['j'], target_cells['k'])],
        "cell_record": cell_records
    }

    return json.dumps(output)

